import{z as r,x as l,o as e,c as s,q as t,j as A,D as E,d as i,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Swaption 的深化","description":"","frontmatter":{"title":"Swaption 的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc-swaption-deep.md","filePath":"quant/rc-swaption-deep.md","lastUpdated":1791413859000}'),p={name:"quant/rc-swaption-deep.md"};function d(m,a,D,C,_,S){const B=l("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="swaption-的深化" tabindex="-1">Swaption 的深化 <a class="header-anchor" href="#swaption-的深化" aria-label="Permalink to &quot;Swaption 的深化&quot;">​</a></h1><div class="epigraph"><p>Swaption 的标的不是债券而是远期起息的互换，其价格是年金计价物下互换利率分布的尾部；把债券期权波动率直接搬来用，第一步就把计价物弄错了。</p><footer>—— 据 Rebonato, *Volatility and Correlation*, 2004；Brigo and Mercurio, *Interest Rate Models*, 2006 整理</footer></div><p><a href="/quant/rc-curve-strategies-deep">上一课</a>把形状观点做成了 DV01 中性的线性持仓，但线性仓表达不了「未来某时点波动放大」或「利率跌破某水平我才受损」这类凸性观点。本课解剖利率期权的标准件 Swaption：把期权化形状观点的定价、报价与对冲一次讲清，为下一课整张利率波动率曲面铺路。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一笔 \\(T\\) 年后进入、期限为 \\(\\tau\\) 的互换期权，在年金计价物下写成</p> \\[V_0 = A_0\\,\\mathbb{E}^{A}\\big[(\\,\\omega (S_T - K)\\,)^+\\big], \\]<p>其中 \\(A\\) 是标的互换的年金，\\(S_T\\) 是行权日互换利率，\\(\\omega=\\pm 1\\) 区分支付者与收取者。缺口有三个：市场按「期权到期 × 互换期限」网格报隐含波动率，负利率出现后对数正态坐标失效怎么办；交易台的 vega 与 bp-vega 怎么换算、对冲用什么工具；以及「远期 Swaption 波动率」这类观点如何用日历价差表达。三件事都挂在同一步上——先选定计价物，公式才有落点。</p><p><span class="marginnote">年金翻译一下：把互换未来所有定盘日的贴现因子加总（再乘每期长度）得到的数，代表「这份互换值多少个 1 基点」。它是 Swaption 定价的分母——正因选它做计价物，远期互换利率才有鞅这类干净的数学性质。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报价侧：网格上每个「到期 × 期限」点是一个独立资产，平值与否、支付者与收取者由 smile 给出不对称的价。负利率用移位对数正态处理：\\(S+b\\) 服从对数正态，\\(b\\) 是随币种与时期约定的移位；同一点也可报正态波动率，两种坐标的换算是近似，成交记录必须写清用哪一种。vega 是价格对波动率的导数，bp-vega 是价格对波动率移动 1bp 的导数，两者差一个年金 \\(A\\) 与行权点密度的因子；对冲用相邻网格点插值，网格上不存在的点不是可交易工具。远期波动观点用日历价差表达：认为一年后五年段的波动会涨，就卖 1y5y、买 2y5y，组合暴露的正是 \\((1,5)\\) 到 \\((2,5)\\) 之间的远期段。<a href="/quant/cms-convexity">CMS 凸性</a>正是用这些香草 Swaption 静态复制出来的，所以这张网格同时是互换期权市场、CMS 与可赎回债的共同基础设施。百慕大 Swaption 的多时点行权让定价吃模型：<a href="/quant/hull-white">Hull–White</a> 或 <a href="/quant/lmm">LMM</a> 校准到哪些点，价格就偏哪些点，机制见<a href="/quant/bermudan-swaption">百慕大互换期权</a>。</p><p><span class="marginnote">数字实例：押「一年后五年段波动上涨」就卖 1y5y、买 2y5y。若 1y5y 的 vega 是 4 万、2y5y 是 3.5 万，要按等 vega 配比才能把其余暴露抵掉、只留 \\((1,5)\\) 到 \\((2,5)\\) 的远期段；金额随手配，会顺手多押一段现价波动而不自知。</span></p>',11)),(e(),A(o,null,{default:E(()=>[n(B,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%8A%A5%E4%BB%B7%E7%BD%91%E6%A0%BC%EF%BC%9A%E5%88%B0%E6%9C%9F%20%C3%97%20%E6%9C%9F%E9%99%90%22%5D%20--%3E%20AN%5B%22%E5%B9%B4%E9%87%91%20A%20%E4%B8%8B%20Black%20%2F%20%E7%A7%BB%E4%BD%8D%E5%AF%B9%E6%95%B0%E6%AD%A3%E6%80%81%22%5D%0A%20%20AN%20--%3E%20V%5B%22vega%20%E4%B8%8E%20bp-vega%20%E6%8D%A2%E7%AE%97%22%5D%0A%20%20AN%20--%3E%20CAL%5B%22%E9%80%90%E7%82%B9%20smile%EF%BC%9ASABR%20%E6%88%96%E6%AD%A3%E6%80%81%E5%9D%90%E6%A0%87%22%5D%0A%20%20CAL%20--%3E%20HEDGE%5B%22%E7%9B%B8%E9%82%BB%E7%BD%91%E6%A0%BC%E7%82%B9%E6%8F%92%E5%80%BC%E5%AF%B9%E5%86%B2%22%5D%0A%20%20Q%20--%3E%20CALSPREAD%5B%22%E6%97%A5%E5%8E%86%E4%BB%B7%E5%B7%AE%EF%BC%9A%E6%8A%BC%E8%BF%9C%E6%9C%9F%E6%B3%A2%E5%8A%A8%E6%AE%B5%22%5D%0A%20%20CALSPREAD%20--%3E%20CMS%5B%22CMS%20%E5%87%B8%E6%80%A7%E4%B8%8E%E7%99%BE%E6%85%95%E5%A4%A7%E6%A0%A1%E5%87%86%E5%85%B1%E7%94%A8%E6%AD%A4%E7%BD%91%E6%A0%BC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>年金计价物是全部机制的枢纽：以 \\(A\\) 为分母，远期互换利率 \\(S_t\\) 才是鞅，Black 公式的分布假设才有意义；换成终端测度，\\(S_T\\) 的期望要加凸性调整——这就是为什么「同一个波动率」在不同测度下不是同一个数。smile 的动力学由到期轴与期限轴共同决定：短到期对央行日程敏感，长期限受均值回复压扁，两轴并不独立。逐点 SABR 校准（<a href="/quant/sabr">SABR</a>，翼部见<a href="/quant/sabr-wing-extrap">SABR 翼部外推</a>）给出的是切片描述，不自动给出两轴的联合演化；把切片当成动态模型，是百慕大定价最常见的模型风险来源之一，两轴联合正是 <a href="/quant/sabr-lmm-calib">SABR 对 LMM 校准</a>一课处理的问题。</p><p><span class="marginnote">常见误区：把移位 \\(b\\) 当成「让公式跑通的小补丁」。同一个 smile 换移位后翼部形状会变，深度虚值的支付者与收取者价格差异可观；跨移位比波动率、跨币种搬参数，都要先统一坐标——否则你比的是坐标，不是市场。</span></p>',3)),(e(),A(o,null,{default:E(()=>[n(B,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20AN%5B%22%E4%BB%A5%E5%B9%B4%E9%87%91%20A%20%E4%B8%BA%E5%88%86%E6%AF%8D%22%5D%20--%3E%20MART%5B%22%E8%BF%9C%E6%9C%9F%E4%BA%92%E6%8D%A2%E5%88%A9%E7%8E%87%20S_t%20%E6%98%AF%E9%9E%85%22%5D%0A%20%20MART%20--%3E%20BLK%5B%22Black%20%E5%88%86%E5%B8%83%E5%81%87%E8%AE%BE%E6%89%8D%E6%88%90%E7%AB%8B%22%5D%0A%20%20TMR%5B%22%E6%8D%A2%E6%88%90%E7%BB%88%E7%AB%AF%E6%B5%8B%E5%BA%A6%22%5D%20--%3E%20CONV%5B%22S_T%20%E6%9C%9F%E6%9C%9B%E8%A6%81%E5%8A%A0%E5%87%B8%E6%80%A7%E8%B0%83%E6%95%B4%22%5D%0A%20%20CONV%20--%3E%20NOTE%5B%22%E5%90%8C%E4%B8%80%E6%B3%A2%E5%8A%A8%E7%8E%87%E5%9C%A8%E4%B8%8D%E5%90%8C%E6%B5%8B%E5%BA%A6%E4%B8%8D%E6%98%AF%E5%90%8C%E4%B8%80%E4%B8%AA%E6%95%B0%22%5D%0A%20%20EXPIRY%5B%22%E5%88%B0%E6%9C%9F%E8%BD%B4%EF%BC%9A%E7%9F%AD%E7%AB%AF%E5%AF%B9%E5%A4%AE%E8%A1%8C%E6%97%A5%E7%A8%8B%E6%95%8F%E6%84%9F%22%5D%20--%3E%20JOINT%5B%22%E4%B8%A4%E8%BD%B4%E4%B8%8D%E7%8B%AC%E7%AB%8B%22%5D%0A%20%20TENOR%5B%22%E6%9C%9F%E9%99%90%E8%BD%B4%EF%BC%9A%E9%95%BF%E6%9C%9F%E9%99%90%E8%A2%AB%E5%9D%87%E5%80%BC%E5%9B%9E%E5%A4%8D%E5%8E%8B%E6%89%81%22%5D%20--%3E%20JOINT%0A%20%20JOINT%20--%3E%20RISK%5B%22%E5%88%87%E7%89%87%20smile%20%E4%B8%8D%E6%98%AF%E5%8A%A8%E6%80%81%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">「1y10y」两个数指一件东西：一年后进入的十年互换期权。vega 与 bp-vega 混报会差出一个年金量级——十年期互换的年金约是名义的八倍，混淆之后对冲名义会放大近一个数量级，而且是单向的：bp-vega 台按 vega 名义下单，就多对冲了八倍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理 caps 与 floors 的逐期结构，那是下一课；也不重讲曲线构建。移位 \\(b\\) 的选择在深度负利率区不是纯技术：同一个 smile 换移位后翼部形状不同，跨移位比较波动率要先统一坐标。百慕大价格对行权边界的数值处理敏感，树、PDE 与最小二乘蒙特卡洛是同一问题的不同近似，报告要写引擎。最后，香草网格的流动性集中在前几个到期与期限，长尾点报价宽，插值出来的「价格」没有交易对手时只是内部记账，不能当对冲工具写进风险表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Swaption 在年金计价物下是互换利率的期权；测度与计价物先于公式，拿债券波动率套用必错。</li><li>负利率时代用移位对数正态或正态报价，坐标与移位必须写进成交与风险记录。</li><li>远期波动观点用同期限不同到期的日历价差表达；vega 与 bp-vega 差一个年金因子。</li><li>香草网格是 CMS 凸性与百慕大校准的公共输入；切片 smile 不是动态模型。</li><li>出处：Rebonato, <em>Volatility and Correlation</em>, 2004；Brigo and Mercurio, <em>Interest Rate Models</em>, 2006；CMS 与百慕大见本栏 cms-convexity、bermudan-swaption 两课。</li></ul>',5))])}const h=r(p,[["render",d]]);export{u as __pageData,h as default};
